package com.example.pizzacrash.game;

import android.content.Context;
import android.content.res.AssetManager;

import org.json.JSONArray;
import org.json.JSONObject;

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;

/**
 * Data-driven level configuration. Levels are generated by deterministic rules
 * (one generator shared by runtime and unit tests) so all 200 levels differ in
 * board size, tile count, moves, objectives, and star thresholds without any
 * per-level hardcoded logic. Optional asset override: assets/levels.json can pin
 * specific values later for hand-tuning.
 */
public final class LevelConfig {

    public static final int WORLDS = 10;
    public static final int LEVELS_PER_WORLD = 20;
    public static final int TOTAL_LEVELS = WORLDS * LEVELS_PER_WORLD; // 200

    public final int globalLevel;   // 1..200
    public final int world;         // 1..10
    public final int localLevel;    // 1..20
    public final int rows, cols, numTypes, moveLimit;
    /** Objective list: each entry is typeId (-1 = score objective) + required amount. */
    public final List<int[]> objectives; // {typeId, amount}; typeId==-1 -> { -1, targetScore }
    public final int star1Score, star2Score, star3Score;
    public final int coinReward;

    private LevelConfig(int globalLevel, int world, int localLevel, int rows, int cols,
                        int numTypes, int moveLimit, List<int[]> objectives,
                        int s1, int s2, int s3, int coinReward) {
        this.globalLevel = globalLevel; this.world = world; this.localLevel = localLevel;
        this.rows = rows; this.cols = cols; this.numTypes = numTypes; this.moveLimit = moveLimit;
        this.objectives = objectives;
        this.star1Score = s1; this.star2Score = s2; this.star3Score = s3;
        this.coinReward = coinReward;
    }

    /** Global index (1-based) -> config. Pure function of level number; testable on JVM. */
    public static LevelConfig forGlobalLevel(int globalLevel) {
        if (globalLevel < 1 || globalLevel > TOTAL_LEVELS) {
            throw new IllegalArgumentException("level out of range: " + globalLevel);
        }
        int world = (globalLevel - 1) / LEVELS_PER_WORLD + 1;
        int local = ((globalLevel - 1) % LEVELS_PER_WORLD) + 1;

        // Difficulty curve parameters
        float w = (world - 1) / 9f;                       // 0..1 across worlds
        float l = (local - 1) / 19f;                       // 0..1 within world
        float d = 0.55f * w + 0.45f * l;                   // combined difficulty 0..1

        // Board grows with difficulty: 7x8 early -> 9x9 late
        int cols = 7 + Math.round(d * 2);                  // 7..9
        int rows = 8 + Math.round(d * 1);                  // 8..9

        // Tile types: 4 early, 5 mid, 6 late
        int numTypes = 4 + (d > 0.35f ? 1 : 0) + (d > 0.7f ? 1 : 0); // 4..6

        // Move limit: generous enough that the objectives below are achievable
        // within the limit (see playability test), tightening with difficulty.
        int moveLimit = 55 - Math.round(d * 12);           // 55..43

        // Objectives: collect N of M ingredient types; more types & higher counts
        // later. Amounts scale DOWN with the number of tile types (more types =
        // each specific ingredient appears less often per match). Targets stay
        // inside what a greedy player clears within the move limit — validated
        // by LevelConfigTest.sampledLevelsAreWinnableByGreedyPlayer over all 200
        // levels.
        List<int[]> objectives = new ArrayList<>();
        int objCount = 1 + Math.round(d * 2);              // 1..3 collect objectives
        float typeFactor = 6f / numTypes;                  // 1.5 .. 1.0
        int baseAmount = Math.round((7 + d * 6) * typeFactor);   // ~10..13
        for (int i = 0; i < objCount; i++) {
            int typeId = (globalLevel + i * 3) % numTypes; // deterministic spread
            int amount = baseAmount + i * 2;               // up to ~20
            objectives.add(new int[]{typeId, amount});
        }
        // Every 5th level also has a score objective layered on top
        if (globalLevel % 5 == 0) {
            objectives.add(new int[]{-1, 600 + Math.round(d * 900)});
        }

        // Star thresholds derived from expected scoring (~10 pts/tile x tiles
        // cleared). star1 is always reachable by just finishing the level; star3
        // rewards efficient play / cascades.
        int est = baseAmount * objCount;                   // rough tiles needed
        int s1 = est * 10;
        int s2 = (int) (s1 * 1.3f);
        int s3 = (int) (s1 * 1.7f);

        // Coin reward scales with world progress
        int coinReward = 20 + world * 5 + local;

        return new LevelConfig(globalLevel, world, local, rows, cols, numTypes,
                moveLimit, objectives, s1, s2, s3, coinReward);
    }

    public static LevelConfig forWorldLevel(int world, int local) {
        return forGlobalLevel((world - 1) * LEVELS_PER_WORLD + local);
    }

    public boolean isScoreObjective(int[] obj) { return obj[0] == -1; }

    /**
     * Optional JSON override hook (assets/levels.json). If the asset exists it may
     * contain {"levels":[{"global":1,"rows":8,...}]} entries that replace generated
     * values. Absent asset -> pure generated config (current shipping state).
     */
    public static LevelConfig load(Context ctx, int globalLevel) {
        LevelConfig generated = forGlobalLevel(globalLevel);
        try {
            AssetManager am = ctx.getAssets();
            JSONArray arr = new JSONObject(slurp(am.open("levels.json"))).optJSONArray("levels");
            if (arr != null) {
                for (int i = 0; i < arr.length(); i++) {
                    JSONObject o = arr.getJSONObject(i);
                    if (o.optInt("global") == globalLevel) return fromJson(o, generated);
                }
            }
        } catch (Exception ignored) {
            // no override file or malformed -> fall back to generated config safely
        }
        return generated;
    }

    private static LevelConfig fromJson(JSONObject o, LevelConfig fallback) throws org.json.JSONException {
        List<int[]> objs = new ArrayList<>();
        JSONArray ja = o.optJSONArray("objectives");
        if (ja != null) {
            for (int i = 0; i < ja.length(); i++) {
                JSONObject jo = ja.getJSONObject(i);
                objs.add(new int[]{jo.optInt("type", -2), jo.optInt("amount", 0)});
            }
        } else {
            objs = fallback.objectives;
        }
        return new LevelConfig(fallback.globalLevel, fallback.world, fallback.localLevel,
                o.optInt("rows", fallback.rows), o.optInt("cols", fallback.cols),
                o.optInt("numTypes", fallback.numTypes),
                o.optInt("moveLimit", fallback.moveLimit), objs,
                o.optInt("star1", fallback.star1Score), o.optInt("star2", fallback.star2Score),
                o.optInt("star3", fallback.star3Score), o.optInt("coinReward", fallback.coinReward));
    }

    private static String slurp(java.io.InputStream in) throws Exception {
        BufferedReader r = new BufferedReader(new InputStreamReader(in));
        StringBuilder sb = new StringBuilder();
        String line;
        while ((line = r.readLine()) != null) sb.append(line);
        r.close();
        return sb.toString();
    }
}
